fenced=False; polished=[]
for line in text.splitlines():
    if line.startswith('```'):fenced=not fenced;polished.append(line);continue
    if fenced or line.startswith('|'):polished.append(line);continue
    protected_text=[]
    def hide(match):
        protected_text.append(match[0]);return '§'+str(len(protected_text)-1)+'§'
    line=re.sub(r'`[^`]+`|!?\[[^\]]*\]\([^)]+\)',hide,line)
    line=re.sub(r'\b(only|at|to|from|with|all|about|than|over|under|per|above|below|epoch|Stage|stage|update|step|batch|full|seq|ctx)(?=\d)',r'\1 ',line)
    line=re.sub(r'(?<=\d)(?=(?:epochs?|updates?|steps?|rows?|cases?|episodes?|tokens?|audits?|minutes?|seconds?|GiB|MiB|GB|kg|W|GPUh|semantic|groups?|conflict|incident|consistent|abstain|questions|exposures|synthetic|OSS|L40S|A100|input|format|validation|holdout|calls?|training|provisional|other))',' ',line)
    line=re.sub(r'%(?=[a-zA-Z])','% ',line)
    line=re.sub(r'(?<=,)(?=[A-Za-z])',' ',line)
    line=re.sub(r'(?<=epoch)(?=SFT)',' ',line)
    for i,value in enumerate(protected_text):line=line.replace('§'+str(i)+'§',value)
    polished.append(line)
text='\n'.join(polished)+'\n' 
